"""Native-only, source-bound fire-station site discovery for C111706.

No station identity is inferred from a CARLA object label alone: an operator
source and exact scene-object/map readback are both required.
"""
import hashlib
import json
from math import hypot
from pathlib import Path


def _sha(data):
    return hashlib.sha256(data).hexdigest()


def _scene_object(world, expected):
    objects = world.get_environment_objects()
    matches = [item for item in objects if item.id == expected['id']]
    if len(matches) != 1:
        raise ValueError('Station scene object absent or ambiguous')
    item = matches[0]
    if item.name != expected['name'] or str(item.type) != expected['type']:
        raise ValueError('Station scene object identity changed')
    actual = item.transform.location
    claimed = expected['location_m']
    if hypot(actual.x-claimed[0], actual.y-claimed[1]) > .25 or abs(actual.z-claimed[2]) > .25:
        raise ValueError('Station scene object transform changed')
    return {'id': item.id, 'name': item.name, 'type': str(item.type),
            'location_m': [float(actual.x), float(actual.y), float(actual.z)]}


def load_native_survey(path, world):
    path = Path(path).resolve()
    raw = path.read_bytes()
    manifest = json.loads(raw.decode('utf-8'))
    if manifest.get('format') != 'worker-fire-station-native-survey-v1':
        raise ValueError('Native station survey format mismatch')
    source = manifest.get('station_source', {})
    if source.get('kind') != 'operator_survey' or not source.get('reviewer') or not source.get('asset_id'):
        raise ValueError('Source-reviewed station identity required')
    if not source.get('source_path'):
        raise ValueError('Station source material path missing')
    material = (path.parent/source['source_path']).resolve()
    if not material.is_file() or _sha(material.read_bytes()) != source.get('source_sha256'):
        raise ValueError('Station source material missing or changed')
    material_bytes = material.read_bytes()
    material_bytes.decode('utf-8')
    world_map = world.get_map()
    opendrive_sha = _sha(world_map.to_opendrive().encode('utf-8'))
    if world_map.name != manifest.get('map_name') or opendrive_sha != manifest.get('opendrive_sha256'):
        raise ValueError('Native station map/OpenDRIVE source changed')
    scene = _scene_object(world, manifest['scene_object'])
    if source['asset_id'] != 'environment-object:' + str(scene['id']):
        raise ValueError('Station asset differs from scene object')
    survey = {key: manifest[key] for key in ('map_name', 'station_source', 'scene_object',
              'public_before', 'public_at', 'public_after', 'driveway_at', 'routes', 'other_route')}
    receipt = {'format': 'worker-fire-station-native-survey-receipt-v1',
               'manifest_sha256': _sha(raw), 'source_material_sha256': source['source_sha256'],
               'map_name': world_map.name, 'opendrive_sha256': opendrive_sha,
               'scene_object': scene, 'station_identity_review_pending': True,
               'physical_acceptance_claimed': False}
    return survey, receipt, raw, material_bytes

"""Four original-frame RGB sources for the fire-station reversal delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer statutory caution or physical signal visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-10.0, 0.0, 8.0), (-12.0, 0.0, 0.0), (1920, 1080), 100),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-5.0, 2.5, 3.5), (-8.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans(overview_height_delta_m=0.):
    if not 0 <= overview_height_delta_m <= 2:
        raise ValueError('Unsupported station overview height delta')
    result = []
    for name, spec in CAMERAS.items():
        location, rotation, size, fov = spec
        if name == 'overview':
            location = (location[0], location[1], location[2] + overview_height_delta_m)
        result.append(CameraPlan(name, location, rotation, size, fov))
    return result


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class FireStationCameraCapture:
    def __init__(self, world, carla_module, subject, sinks,
                 *, overview_height_delta_m=0.):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans(overview_height_delta_m):
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Source-bound fire-station entrance geometry for C111706 construction.

The caller must identify a real fire-station asset and the public-road/driveway
lane pair in the local map survey. This module rejects a merely labelled U-turn.
It does not establish that the surveyed asset is a fire station.
"""

from dataclasses import dataclass
from math import atan2, cos, hypot, pi, sin


@dataclass(frozen=True)
class Point:
    x: float
    y: float


def _point(location):
    return Point(float(location.x), float(location.y))


def _heading(a, b):
    return atan2(b.y - a.y, b.x - a.x)


def _wrap(angle):
    return atan2(sin(angle), cos(angle))


def _lane_identity(waypoint):
    return (waypoint.road_id, waypoint.lane_id)


def _rectangle(a, b, half_width):
    dx, dy = b.x-a.x, b.y-a.y
    length = hypot(dx, dy)
    if length == 0: raise ValueError('zero-length mapped station segment')
    nx, ny = -dy/length*half_width, dx/length*half_width
    return [[a.x+nx, a.y+ny], [b.x+nx, b.y+ny],
            [b.x-nx, b.y-ny], [a.x-nx, a.y-ny]]


def _inside(point, polygon):
    x, y = point
    inside = False
    for a, b in zip(polygon, polygon[1:]+polygon[:1]):
        if (a[1] > y) != (b[1] > y) and x < (b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:
            inside = not inside
    return inside


def _hull(points):
    points = sorted(set((float(x),float(y)) for x,y in points))
    if len(points)<3:raise ValueError('body footprint lacks three distinct vertices')
    def cross(o,a,b):return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lower=[];upper=[]
    for point in points:
        while len(lower)>=2 and cross(lower[-2],lower[-1],point)<=0:lower.pop()
        lower.append(point)
    for point in reversed(points):
        while len(upper)>=2 and cross(upper[-2],upper[-1],point)<=0:upper.pop()
        upper.append(point)
    return lower[:-1]+upper[:-1]


def _edges_cross(a,b,c,d):
    def orient(p,q,r):return (q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0])
    return orient(a,b,c)*orient(a,b,d)<0 and orient(c,d,a)*orient(c,d,b)<0


def _overlap(body, polygon):
    body = _hull(body)
    return (any(_inside(v, polygon) for v in body) or
            any(_inside(v, body) for v in polygon) or
            any(_edges_cross(a,b,c,d) for a,b in zip(body,body[1:]+body[:1])
                for c,d in zip(polygon,polygon[1:]+polygon[:1])))


def validate_entrance(public_before, public_at, public_after, driveway_at, *,
                      source, min_branch_angle_deg=35):
    """Validate measured map geometry; return a reproducible local reference.

    All waypoints are original map waypoints chosen by a survey, not inferred
    from legal labels. A driveway must be a distinct lane diverging from the
    public lane near its entrance. The source binds a map landmark or survey.
    """
    if not isinstance(source, dict) or source.get('kind') not in ('map_landmark', 'operator_survey', 'authored_diagnostic'):
        raise ValueError('source-bound fire-station identification required')
    if not source.get('asset_id') or not source.get('source_sha256'):
        raise ValueError('fire-station source asset and hash required')
    if len(source['source_sha256']) != 64:
        raise ValueError('fire-station source SHA256 malformed')
    if _lane_identity(public_before) != _lane_identity(public_at) or _lane_identity(public_after) != _lane_identity(public_at):
        raise ValueError('public approach is not one continuous lane')
    if _lane_identity(driveway_at) == _lane_identity(public_at):
        raise ValueError('driveway is not a separate lane')
    before = _point(public_before.transform.location)
    at = _point(public_at.transform.location)
    after = _point(public_after.transform.location)
    driveway = _point(driveway_at.transform.location)
    if not 2.0 <= hypot(after.x - before.x, after.y - before.y) <= 40.0:
        raise ValueError('public approach sample spacing invalid')
    if hypot(driveway.x - at.x, driveway.y - at.y) > 12.0:
        raise ValueError('driveway is too far from public entrance')
    public_heading = _heading(before, after)
    driveway_heading = _heading(at, driveway)
    branch_angle = abs(_wrap(driveway_heading - public_heading)) * 180 / pi
    if branch_angle < min_branch_angle_deg:
        raise ValueError('driveway lacks a physical branch angle')
    return {
        'source': dict(source),
        'public_lane': _lane_identity(public_at),
        'driveway_lane': _lane_identity(driveway_at),
        'entrance_xy_m': [at.x, at.y],
        'public_heading_rad': public_heading,
        'driveway_heading_rad': driveway_heading,
        'branch_angle_deg': branch_angle,
        'entrance_polygon_xy': _rectangle(at, driveway, max(1.5, float(driveway_at.lane_width)/2)),
        'approach_polygon_xy': _rectangle(before, at, max(1.5, float(public_at.lane_width)/2)),
    }


def classify_path(samples, geometry, *, entrance_radius_m=5.0):
    """Describe realized center path without assigning a legal conclusion.

    Samples contain original-frame position and heading. A reversal requires
    observed motion on both sides of the episode; a driveway visit requires
    a measured position on its distinct mapped lane.
    """
    if len(samples) < 3:
        raise ValueError('original path has fewer than three samples')
    frames = [s['frame'] for s in samples]
    if frames != sorted(set(frames)):
        raise ValueError('original frame identities are not unique and increasing')
    x0, y0 = geometry['entrance_xy_m']
    near = [s['frame'] for s in samples if hypot(s['x_m'] - x0, s['y_m'] - y0) <= entrance_radius_m]
    driveway = [s['frame'] for s in samples if tuple(s['lane_id']) == tuple(geometry['driveway_lane'])]
    body_entrance = [s['frame'] for s in samples if s.get('body_vertices_xy') and
                     _overlap(s['body_vertices_xy'], geometry['entrance_polygon_xy'])]
    body_approach = [s['frame'] for s in samples if s.get('body_vertices_xy') and
                     _overlap(s['body_vertices_xy'], geometry['approach_polygon_xy'])]
    delta = abs(_wrap(samples[-1]['heading_rad'] - samples[0]['heading_rad'])) * 180 / pi
    return {
        'heading_change_deg': delta,
        'reversal_observed': delta >= 150.0,
        'near_entrance_frames': near,
        'driveway_frames': driveway,
        'body_entrance_overlap_frames': body_entrance,
        'body_approach_overlap_frames': body_approach,
        'entered_driveway': bool(driveway),
        'in_front_of_entrance_observed': bool(near),
        'purpose_of_turning': 'unresolved_contextual_judgment',
        'physical_fire_station_identity': 'unresolved_until_source_review',
    }

